// Reference solution
function toBase62(n) {
  const A = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
  if (!Number.isSafeInteger(n) || n < 0) throw new RangeError('n must be an integer ≥ 0');
  let s = '';
  do { s = A[n % 62] + s; n = Math.floor(n / 62); } while (n > 0);
  return s;
}

