function checkCreate(body, taken, base) {
  // Write your solution here
  if (!body.url) return { status: 422, code: 'INVALID_URL' };
  if (taken.includes(body.alias)) return { status: 409, code: 'ALIAS_TAKEN' };
  return null;
}

